  "shell.lane.slotKeyRefused.flex.notYetDax": "Nexus 未在 {{time}} UTC 键控 {{mode}} 通联：Flex 原生 DAX 音频已开启，但电台尚未从其经 DAX 接收来自 Nexus 的发射音频。未发出任何内容，发射已关闭。Nexus 会在片刻内完成电台设置；随后请重新开启发射。",
  "shell.lane.slotKeyRefused.flex.daxUnfed": "Nexus 未在 {{time}} UTC 键控 {{mode}} 通联：Flex 原生 DAX 音频已关闭，但电台仍按 Nexus 所设从其经 DAX 接收发射音频，而此刻 DAX 无输入。未发出任何内容，发射已关闭。Nexus 会在片刻内将电台切回麦克风输入；随后请重新开启发射。",
  "shell.lane.slotKeyRefused.txAudio": "Nexus 未在 {{time}} UTC 键控电台，因为发射音频输出无法打开（{{why}}）。未发出任何内容，发射已关闭。请检查设置中的输出设备（TX）（可能有其他程序占用，或设备已拔出），然后重新开启发射。",
  "shell.lane.slotUnkeyFailed.message": "PTT 关闭失败——发射停止",
  "shell.lane.slotUnkeyFailed.detail": "电台在 {{time}} UTC 未接受 PTT 关闭（{{why}}），因此发射已关闭。它可能仍在发射：请立即检查电台。Nexus 会持续发送 PTT 关闭指令，直到电台接受。待电台恢复接收后再重新开启发射。",
  "shell.lane.slotAudioLost.message": "通联结束——发射停止",
  "shell.lane.slotAudioLost.detail": "承载某次通联音频至电台的路由（Flex DAX 或 TCI）在该次通联中途于 {{time}} UTC 中断，因此其余部分会静默发出。Nexus 就此结束该次通联并关闭发射。请重新开启发射以继续。",
  "shell.lane.slotOverDropped.message": "通联丢弃——电台键控过晚",
  "shell.lane.slotOverDropped.detail": "此次通联被丢弃：电台仅在 {{time}} UTC 键控，即你的时隙结束后 {{late}}（CAT 较慢），因此 Nexus 立即解除键控且未发送任何内容，并保持发射开启以等待你的下一次通联。分频操作会在每次键控前向电台发送指令，在慢速 CAT 链路上可能耗时数秒：若此情况持续，请检查设置中的 CAT 链路与分频操作。",
  "shell.lane.pttRefused.message": "PTT 被拒",
