  "shell.lane.voiceDropped.keyed": "Nexus 未在 {{time}} UTC 播放语音消息：另有程序正在发射或已先行键控电台（你的麦克风或 PTT、一个调谐载波、另一程序），因此未键控任何内容。该消息被丢弃而非暂存。",
