  "gettingStarted.station.callsign": "<b>呼号</b>——以大写存储。在设置有效的呼号之前，Nexus 不会启动 PSK Reporter 或 RBN/cluster 馈送：3–10 个字符，至少包含一个字母和一个数字。",
  "gettingStarted.station.grid": "<b>网格</b>——你的梅登海德定位格。QRZ 可显示你的。",
  "gettingStarted.station.name": "<b>姓名</b>——可选，在设置 ▸ 本台中。供 CW 宏 <code>{NAME}</code> 与日志簿自动填充使用。",
  "gettingStarted.station.callout.label": "请填写全部六位字符",
  "gettingStarted.station.callout.body": "四位字符会把你钉在约 100 英里方格的中心，而你将来读到的每个距离与方位都从这一点起算。<code>{{full}}</code> 优于 <code>{{short}}</code>。格式错误的定位格会被直接拒绝——向导不会让你越过它。",
  "gettingStarted.station.shot.caption": "设置向导 ▸ 第 1 步 · 可随时从设置 ▸ 外观 ▸ 功能重新运行",
  "gettingStarted.station.shot.title": "谁在电波上？",
  "gettingStarted.station.shot.sub": "你的网格是任何基于位置的锚点——卫星过境、传播、地图与 DX 远征窗口都由它算出。",
  "gettingStarted.station.shot.callsignLabel": "呼号",
  "gettingStarted.station.shot.gridLabel": "网格",
  "gettingStarted.station.shot.gridHint": "梅登海德定位格（qrz.com 可显示你的）。请填写全部 6 位——4 位字符会把你钉在约 100 英里方格的中心。",
  "gettingStarted.station.shot.skip": "我自己来设置",
  "gettingStarted.station.shot.next": "下一步 →",
  "gettingStarted.radio.aria": "第 2 / 4 步：你的电台",
  "gettingStarted.radio.eyebrow": "第 2 / 4 步 · 你的设备",
  "gettingStarted.radio.heading": "电台如何连接？",
  "gettingStarted.radio.lede": "一个按钮完成排查。Nexus 读取 USB 描述符、匹配电台型号、配对音频编解码器，并在一次扫描中查找你网络上的 FlexRadio。",
  "gettingStarted.radio.where": "在向导中，或在<b>设置 ▸ 电台 ▸ 设备与 CAT</b>，点击<b>检测我的电台</b>。",
  "gettingStarted.radio.pickRow": "<b>选择属于你的电台那一行。</b>它会一次性填好端口、Hamlib 型号与两个音频设备。在双 UART 的 Icom 上，两行描述同一台设备——请选标注为<em>CI-V 端口——用这个</em>的那行。",
  "gettingStarted.radio.genericCable": "<b>通用线缆？</b>一个只报告“USB Serial”的 CH340 会填好端口与音频，但型号留空——请从下拉菜单中选择。",
  "gettingStarted.radio.flex": "<b>FlexRadio</b> 在网络上被发现，并以经 WSJT-X 验证的方式配置：通过 SmartSDR CAT 应用在 <code>127.0.0.1:5002</code> 进行 CAT，音频经由 DAX。",
  "gettingStarted.radio.testCat": "<b>然后按下 Test CAT。</b>Nexus 保存你的输入，为该电台启动 <code>rigctld</code>，并报告它读回的本振频率——或具体的错误。其他程序通过“设置 ▸ 电台 ▸ <em>发射限制与共享</em>”中的地址共享该电台。",
  "gettingStarted.radio.callout.label": "什么都没找到？",
  "gettingStarted.radio.callout.body": "USB：插上并开机。Flex：必须在同一网络上。无论哪种你都可以跳过，稍后设置——向导从不在硬件上阻塞。在发射前，将<b>发射电平</b>（默认 0.9）调低，直到你的电台 ALC 读数为零。",
  "gettingStarted.radio.shot.caption": "设置向导 ▸ 第 2 步 · Hamlib 随安装包内置",
  "gettingStarted.radio.shot.captionMac": "设置向导 ▸ 第 2 步 · CAT 需要 Homebrew Hamlib——在终端中：brew install hamlib",
  "gettingStarted.radio.shot.title": "电台如何连接？",
  "gettingStarted.radio.shot.sub": "一次检测找到一切——USB 电台与网络上的 FlexRadio。可跳过；稍后“设置 ▸ 电台 ▸ 设备与 CAT”中都有。",
  "gettingStarted.radio.shot.detect": "🔍 检测我的电台",
