  "gettingStarted.radio.shot.usbBlurb": "多数电台——一根线",
  "gettingStarted.radio.shot.netLabel": "网络",
  "gettingStarted.radio.shot.netBlurb": "SDR 软件，或远程电台",
  "gettingStarted.radio.shot.audioIn": "音频输入",
  "gettingStarted.radio.shot.audioOut": "音频输出",
