  "gettingStarted.license.aria": "第 3 / 4 步：执照等级",
  "gettingStarted.license.eyebrow": "第 3 / 4 步 · 你的执照",
  "gettingStarted.license.heading": "申报你的等级，获得真正的锁定",
  "gettingStarted.license.lede": "这一个字段会成为应用中<em>每一条</em>发射路径的软件守卫。Nexus 把本振停在你的授权频段内，并拒绝在其外键控，同时弹出说明原因的提示。",
  "gettingStarted.license.where": "在向导的最后一步，位于<b>你的执照是什么？</b>下。点击的瞬间即被保存。",
  "gettingStarted.license.technician": "40 米上的<b>技术员级</b>被限定在 CW 段——其外的话音与 FT8 发射被阻止。",
  "gettingStarted.license.general": "<b>普通级</b>在 20 米低端 Extra 专属部分不能发射。",
  "gettingStarted.license.sixty": "含信道化的<b>60 米</b>段。",
  "gettingStarted.license.outsideUs": "美国境外？选<b>美国境外</b>。锁定仅建模美国 FCC Part 97 / ITU 第 2 区，因此是关闭而非错误。",
  "gettingStarted.license.callout.label": "它是一张安全网",
  "gettingStarted.license.callout.body": "你有责任了解自己的权限。锁定拦下的是疏忽，而非替代知识。全新安装默认为<b>开放</b>，因此在你明确之前不会悄悄限制任何东西。",
  "gettingStarted.license.shot.caption": "设置向导 ▸ 第 4 步 · 一切从开启状态开始——这是唯一的问题",
  "gettingStarted.license.shot.title": "你的执照是什么？",
  "gettingStarted.license.shot.sub": "设定你的发射权限——应用把本振停在授权频段内，不会让你在其外发射。选“美国境外”则无限制。",
  "gettingStarted.license.shot.technician": "技术员级",
  "gettingStarted.license.shot.technicianBlurb": "美国——有限的 HF + 完整 VHF/UHF",
  "gettingStarted.license.shot.general": "普通级",
  "gettingStarted.license.shot.generalBlurb": "美国——大部分 HF 权限",
  "gettingStarted.license.shot.extra": "业余特级（Extra）",
  "gettingStarted.license.shot.extraBlurb": "美国——完整权限",
  "gettingStarted.license.shot.outside": "美国境外",
  "gettingStarted.license.shot.outsideBlurb": "无发射限制",
  "gettingStarted.license.shot.toast": "发射被阻止——{{freq}} 超出你在 40 米上的普通级话音权限。",
  "gettingStarted.log.aria": "第 4 / 4 步：你的 ADIF 日志",
  "gettingStarted.log.eyebrow": "第 4 / 4 步 · 重要的一项",
  "gettingStarted.log.heading": "导入你现有的日志",
  "gettingStarted.log.lede": "一个日志，所有模式。导入一个 ADIF 文件，应用便知道你已通联过的每个电台、仍需的每个实体，以及距下一个奖项究竟多远——数字、话音与 CW 皆然，由你自己的历史离线算出。",
  "gettingStarted.log.without.label": "无日志时",
  "gettingStarted.log.without.body": "每个呼号看起来都一样，无论它来自译码、cluster 频点还是波段上的语音。每个电台都是新的。缺项面板无话可说。",
  "gettingStarted.log.b4.label": "有日志——曾通联",
  "gettingStarted.log.b4.body": "只要呼号出现就有 B4 标记——数字译码、呼号名单、频点，以及话音与 CW 操作台中的调用卡片。",
  "gettingStarted.log.needed.label": "有日志——缺项面板",
  "gettingStarted.log.needed.body": "新的 DXCC、新的州、新的网格、新的波段槽位——跨所有波段与模式一次排好序，并附上说明其当前可通联的证据。",
  "gettingStarted.log.awards.label": "有日志——奖项",
  "gettingStarted.log.awards.body": "DXCC、Challenge、Honor Roll、WAS、WAZ、VUCC 与 IOTA——与模式无关及分模式皆然——导入完成的瞬间即显现。",
  "gettingStarted.log.sources.head": "你的 ADIF 从何而来",
  "gettingStarted.log.sources.intro": "任何标准 ADIF 导出——<code>.adi</code> 或 <code>.adif</code>。如果你一直在操作，你已有一个。",
  "gettingStarted.log.sources.wsjtx": "<b>WSJT-X</b>——日志目录中的 <code>wsjtx_log.adi</code>。",
  "gettingStarted.log.sources.qrz": "<b>QRZ Logbook</b> 或 <b>LoTW</b>——下载你完整的 ADIF 导出。",
  "gettingStarted.log.sources.others": "<b>N1MM+、Log4OM、HRD、ClubLog</b>——从日志簿导出 ADIF。",
  "gettingStarted.log.import.head": "然后导入它",
  "gettingStarted.log.import.body": "向导第 3 步，或随时在<b>日志簿 ▸ 导入 ADIF</b>。想导入多少文件都行——重复项会被检测并跳过，因此第二次导入毫无损失。",
  "gettingStarted.log.callout.label": "没有任何数据离开你的电脑",
  "gettingStarted.log.callout.body": "导入在本地进行。你的日志保存在你本机的 <code>log.adi</code> 中，奖项引擎离线针对它计算。上传到 LoTW、QRZ、ClubLog 或 eQSL 是独立的、需主动开启的连接器。",
  "gettingStarted.log.shot.caption": "设置向导 ▸ 第 3 步 · 或日志簿 ▸ 导入 ADIF，随时",
  "gettingStarted.log.shot.title": "导入你现有的日志",
  "gettingStarted.log.shot.sub": "Nexus 在了解你的历史时表现最佳。导入 ADIF 日志正是<b>曾通联</b>标记、<b>缺项</b>面板与你<b>奖项</b>进度的来源——没有它，应用盲目启动，把每个电台当新的对待。",
  "gettingStarted.log.shot.import": "导入我的 ADIF 日志…",
  "gettingStarted.log.shot.result": "✓ 已导入 <b>{{count}}</b> 个 QSO · {{present}} 个已存在。你的曾通联与缺项面板现已播种。",
  "gettingStarted.log.shot.formats": "来自 WSJT-X、N1MM、Log4OM、HRD、QRZ、LoTW、ClubLog——任何标准 ADIF（.adi/.adif）导出。没有任何数据离开你的电脑；重复项会被检测并跳过。",
  "gettingStarted.log.closing.eyebrow": "你已就绪——现在去通联吧",
  "gettingStarted.log.closing.digital": "打开<b>数字</b>。本振从 {{freq}} 起步，译码器运行于每个 15 秒时隙——没有需要记的监控开关。",
  "gettingStarted.log.closing.decodes": "在一两个周期内，译码填满波段活动——现在标注了国家、B4 与<b>新 / DXCC</b> 徽章，因为你导入了日志。",
  "gettingStarted.log.closing.doubleClick": "<b>双击</b>一个正在呼叫 CQ 的电台。定序器跑完整个交换并自动记录。同一份日志供话音与 CW 操作台使用，因此熟悉的呼号在那里也会显示其姓名与你的历史。",
  "gettingStarted.wsjtx.label": "来自 WSJT-X？捷径",
  "gettingStarted.wsjtx.body": "你的肌肉记忆能迁移——双击语义、<code>Esc</code> / <code>F4</code> / <code>F6</code> / <code>Alt+1–6</code>、波段活动底部固定、11.8 秒的早期译码、Fake-It 分频、Hound 自动移动。你的设置也能：把第 2 步指向 WSJT-X 所用的同一台设备与音频设备，并把第 4 步交给你的 <code>wsjtx_log.adi</code>。一旦在“设置 ▸ 日志与连接 ▸ <a>集成与订阅</a>”中开启<b>WSJT-X UDP API</b>（默认关闭），JTAlert 与 GridTracker 会继续工作。其地址已与 WSJT-X 默认一致，因此无需设置其他，它们把 Nexus 当作 WSJT-X 看待。",
  "gettingStarted.wsjtx.mac": "在 Mac 上，按住 Fn 使用 F 键——或在系统设置 ▸ 键盘中开启“将 F1、F2 等键用作标准功能键”，如同 WSJT-X。",
  "radios.picker.aria": "选择电台",
