  "assist.state.unassisted": "非辅助",
  "assist.state.assisted": "辅助",
  "assist.sources.off": "辅助来源关闭：CW 译码器、DX cluster / RBN、PSK Reporter 缺项、Super Check Partial、呼号历史。",
  "assist.sources.offSince": "自 {{since}} 起辅助来源关闭：CW 译码器、DX cluster / RBN、PSK Reporter 缺项、Super Check Partial、呼号历史。",
  "assist.sources.on": "CW 译码器、DX cluster / RBN、PSK Reporter 缺项、Super Check Partial 与呼号历史正在提供呼号与交换辅助。",
  "assist.sources.onSince": "自 {{since}} 起，CW 译码器、DX cluster / RBN、PSK Reporter 缺项、Super Check Partial 与呼号历史正在提供呼号与交换辅助。",
  "assist.toggle.declare": "申报非辅助参赛",
  "assist.toggle.end": "结束非辅助参赛",
  "assist.why.summary": "这对你的比赛类别意味着什么",
  "assist.why.cqww": "<b>CQ WW</b> 规则 VIII.2 将“CW 译码器、DX cluster、DX spotting 网站……本地或远程的呼号与频率译码技术（如 CW Skimmer 或 Reverse Beacon Network）”计为 QSO 寻找辅助。使用其中任何一项都会将参赛归入<b>单人辅助（Single Operator Assisted，V.A.2）</b>而非单人（V.A.1）。",
  "assist.why.arrl": "<b>ARRL</b> 比赛称之为 spotting 辅助，并点名“PSKReporter、Telnet、DX spotting 网站或公告板系统、自动化多通道译码器”。单人不可使用它（HCAT.1.1：“不允许使用 spotting 辅助。”）。<b>单人无限（Single Operator Unlimited）</b>可以使用（HCAT.2.1）。ARRL 术语表将多通道译码器定义为“同时显示多个已译码信号”的软件。Nexus 一次只译码一个信号，因此该定义并不描述其 CW 译码器。但它确实描述了 cluster、RBN 与 PSK Reporter 馈送。",
  "assist.why.ownDecodes": "你电台自身的<b>数字译码</b>（含 FT8 与 FT4）在非辅助模式下仍持续供给缺项面板。两套规则都未将它们单独列出：两者都将任何能识别呼号或倍乘数的技术计为辅助，因此若你的比赛将它们计入，请勿用缺项面板来寻找电台。你向外的 PSK Reporter 上传也持续运行，因为 ARRL 说“为他人站生成 spotting 信息不被视为 spotting 辅助”。",
  "assist.why.notCovered": "<b>此开关未覆盖：</b>POTA 与 SOTA activator spots 仍会到达。两套规则都未点名这些馈送，但都将辅助定义得足够宽泛以纳入它们，因此若你参加的比赛将它们计入，请手动关闭 POTA/SOTA 功能。",
  "assist.why.checkRules": "规则因比赛而异，且年间会变化，因此<b>请查阅你所参加比赛的规则</b>。本说明报告 CQ WW 与 ARRL 目前公布的规则。它不是类别裁决。",
  "assist.keep": "你自己的设置从不被重写。结束非辅助模式会完全按你原先的样子恢复译码器与馈送。",
