  "logbook.tools.bulk.uploads": "批量编辑绝不会修改已通联的呼号。从此处不会发送任何内容。若 STATION_CALLSIGN 被替换为另一个呼号，则该呼号是通联上传所用的呼号，因此其上传标记会被清除，下次上传会以新呼号重新发送，并且其 LoTW、eQSL 和 QRZ 确认（在旧呼号下匹配）也会被清除；纸质 QSL 卡片保留。填写空白的 STATION_CALLSIGN、清除它，或添加/移除 /P，都不会清除任何上传标记或确认。但若某通联没有 STATION_CALLSIGN，则会以“设置”中的呼号上传，因此填写或清除可能将通联发送到的呼号变更为某个尚未发送过的服务：确认信息会列出这些。所有其他字段均保留其上传标记与确认。",
