  "settings.pounce.legend": "扑击 — 新目标提醒",
  "settings.pounce.note": "当所需电台出现在集群或 RBN 上的瞬间即打断你，而非等待点报板刷新。无论 Nexus 是否是你正在看的窗口，都会播放响亮提示音，横幅提供一键通联。默认关闭，需手动开启。“罕见”有多罕见取决于你自身的统计：若你正在追逐前一百个实体，则几乎每个 DX 点报都是新目标，此功能会喋喋不休。当你的日志足够丰富、新目标确实成为事件时，再从 <em>仅新 DXCC 实体</em> 开始。每个电台在每个频段和模式仅提醒一次。",
