  "settings.radios.add.action": "+ 添加电台",
  "settings.radios.hint.multi": "下方的电台 / CAT + 音频设置编辑“{{name}}”。每台电台都有自己的 CAT + 音频 — 点击任意电台的“编辑”即可配置它，而不会改变你正在操作的电台；“设为活动”则交换你的操作电台。以下这些电台 / CAT 控制是全站的，因此更改一项会影响所有电台：“接口在 CAT 端口触发 RTS”、“分频操作”、“跟随电台的分频”、“滚轮调谐灵敏度”，以及在高级下的“共享端口”、“串行握手”和“启动时键控线”。",
