  "settings.audio.txPower.label": "发射功率",
  "settings.audio.txPower.aria": "发射驱动电平",
  "settings.audio.txPower.hint": "送入电台的音频 <b>驱动</b> — 与驾驶舱 <b>功率</b> 滑块是同一控制（现在始终一致）。下调直到电台的 ALC 刚好为零。这 <em>不是</em> 电台的 RF 瓦数 — 那些在电台上设置。",
  "settings.audio.rxLevel.label": "RX 电平",
