  "settings.audio.rxLevel.hint": "类似 WSJT-X 的 dB 刻度 — 目标约 30 dB。约 15–60 dB 范围内都能正常解码；红色表示过热（调低 RX 增益或电台音频）。",
  "settings.audio.rxGain.label": "RX 增益",
  "settings.audio.rxGain.aria": "RX 采集增益",
  "settings.audio.rxGain.hint": "提升安静的接口直到 RX 电平读至约 30 dB — 仪表会在你松开滑块时响应。除非仪表读数偏低（低于约 15 dB），否则保持 ×1.0 — FT8 在小信号上也能解码，因此你很少需要很多。",
  "settings.audio.multiRadio.levelHint": "<b>保存</b> 为 <b>{{radio}}</b> 存储此项，并在该电台使用时生效；当前正在使用的电台不改变。",
  "settings.transmit.legend": "发射限制与共享",
  "settings.transmit.bandEdgeTones.label": "频段边缘提示音",
  "settings.transmit.bandEdgeTones.hint": "当刻度盘越过你的执照权限时发出简短音频提示 — 回到频段内为上升的“叮”，越过边缘为下降的“咚”。适用于所有模式。",
  "settings.transmit.powerCaps.label": "按模式限制最大功率（安全）",
  "settings.transmit.powerCaps.hint": "每种模式的 RF 输出上限 — 留空为满功率。FT8/FT4/RTTY 占空比约 100%，因此限制数字模式（如 30%）可保护你的末级和任何放大器。一旦进入受限模式，电台即降至上限，而非仅在你动功率滑块时。",
  "settings.transmit.swrStop.label": "SWR 过高时停止发射",
  "settings.transmit.swrStop.threshold": "高于以下值时停止",
  "settings.transmit.swrStop.hint": "连续两次读数高于此值，Nexus 即停止发射，与停止 TX 完全相同，并告知原因。它从不发起发射，也从不重新开启 TX — 待天线整理好后由你操作。默认关闭；单次轮询的高读数会被忽略，因此调谐器步进或按键瞬态不会切断你。",
  "settings.transmit.swrStop.unverified": "此电台的 SWR 读数尚未验证，因此 Nexus 不会据此停止你的发射。Nexus 仅在知道电台自身刻度时才信任该数值 — 原生 CI-V 的 Icom，以及 FlexRadio。在其他电台上该数值可能偏差很大：有些在自己表上显示近乎完美匹配，却在此报告故障。",
  "settings.transmit.swrStop.noMeterStream": "Nexus 未收到此 Flex 自身的 SWR 表，因此无论 SWR 多高，此切断都不会停止任何发射。该表来自电台的原生数据流，且当前关闭。在 设置 ▸ 电台 ▸ 电台与 CAT 中开启“Flex 原生全景适配器（测试版）”以启动它。在此之前此设置无效。",
  "settings.transmit.parsecStop.label": "若我的 Parsec 会话断开则停止锁存发射",
  "settings.transmit.parsecStop.hint": "用于在 Parsec 上运行机房。Nexus 监视本机上 Parsec 自身的日志。若已连接的 Parsec 会话断开，或其日志无法再读取，Nexus 会停止锁存的 PTT、连续 RTTY 或 PSK，以及调谐，与其自身的停止完全相同，并说明原因。它从不发起发射或重新开启 TX。FT8/FT4 周期不受影响：它们自行结束，且 TX 看门狗仍然适用。Parsec 可能需要近一分钟才注意到拔掉的网络线，因此这是看门狗的备份而非替代。",
  "settings.transmit.parsecStop.unavailable": "仅在 Windows 上可用，Nexus 可在其上读取 Parsec 主机的日志。",
  "settings.transmit.parsecStop.status.starting": "正在检查 Parsec 日志…",
  "settings.transmit.parsecStop.status.connected": "已连接一个 Parsec 会话。若断开，锁存发射将停止。",
  "settings.transmit.parsecStop.status.notConnected": "未连接任何 Parsec 会话，因此不会停止任何发射。",
  "settings.transmit.parsecStop.status.unreadable": "Nexus 无法找到或读取 Parsec 的日志（它在 %APPDATA%\\Parsec 和 %ProgramData%\\Parsec 中查找 log.txt），因此在能够读取之前不会停止任何发射。",
  "settings.remoteStream.label": "从我的浏览器串流此电台",
  "settings.remoteStream.hint": "你批准用于电台控制、且正持有控制的浏览器，会显示此 Nexus 窗口，并可像你在此处一样操作它，包括发射。它的点击和按键仅送达 Nexus，绝不会触及本机其他任何内容。仅发送此窗口：在窗口外打开的对话框（如文件选择器）不会发送，最小化的窗口不发送任何内容。串流端到端加密。浏览器连接期间，若连接断开，所有发射在五秒内停止；若画面冻结，在七秒内停止。",
  "settings.remoteStream.display": "串流就是 Windows 在本机上绘制的此窗口，因此在浏览器串流期间，保持 Nexus 打开且不要最小化。",
  "settings.remoteStream.unavailable": "目前仅限 Windows。",
  "settings.remoteStations.unavailable": "目前仅限 Windows。其他平台请在浏览器中打开远程。",
  "settings.transmit.note": "保存会实时应用你的电台设置（无需重启）。<b>测试 CAT</b> 会保存、启动内置的 <code>rigctld</code>（Hamlib 随 Nexus 在 Windows 上提供 — 无需单独安装），并读取你的电台频率以确认 CAT。对于 CAT，选择你的 <em>电台型号</em> 和 <em>串口</em>；串行 RTS/DTR 与 VOX 无需型号。",
  "settings.transmit.backup.label": "备份你的设置",
  "settings.transmit.backup.action": "备份",
  "settings.transmit.backup.title": "将你的电台、偏好、记忆频道和关注列表保存到文件",
  "settings.transmit.backup.hint": "你的电台、操作偏好、记忆频道、关注列表和追逐集集中于一个文件 — 用于新电脑，或重建前。<b>它不含任何密码或 API 密钥</b>：那些保留在你的操作系统钥匙串中，因此恢复时会再次索要，文件可放心存于 U 盘。你的联络日志是独立的 — 从日志簿导出。恢复会替换你当前的设置。",
  "settings.transmit.backup.appearance": "它还携带 Nexus 的外观：主题、颜色、文字大小、密度、夜间与瀑布图调色板，恢复时会还原这些。现场模式与 UI 缩放随每台电脑保留。",
  "settings.transmit.backup.done": "设置已备份 → {{path}}",
  "settings.transmit.backup.saveAs": "另存为…",
  "settings.transmit.backup.saveAs.title": "备份到你选择的文件夹（备份直接存入下载）",
  "settings.transmit.backup.failed": "备份失败",
