  "settings.transmit.restore.title": "用已保存的备份替换当前设置",
  "settings.transmit.share.label": "与其他程序共享此电台",
  "settings.transmit.share.copy.action": "复制",
  "settings.transmit.share.moved": "{{wanted}} 已被占用（另一程序正在该处监听，或它是你电台自身的 rigctld 地址），因此 Nexus 将其留空，改为在 {{port}} 共享。将其他程序指向此地址。",
  "settings.transmit.share.copy.title": "复制地址以粘贴到其他程序",
  "settings.transmit.share.hint.on": "Nexus 自身在此地址应答，因此 <b>VarAC</b>、<b>FreeDV</b>、<b>WSJT-X</b>、<b>JS8Call</b> 和 <b>fldigi</b> 可在 Nexus 运行时使用电台 — 选择电台 <em>Hamlib NET rigctl</em>（VarAC 与 FreeDV 称之为网络或 rigctld 连接），填入上方地址，并将其串口留空。即使 Nexus 测试或重新配置电台链路，它们仍保持连接，并跟随当前活动电台。仅限本机 — 该地址无法从网络访问。立即生效。两个程序都能指令电台，因此若你同时调谐两者，它们会“争执”。",
  "settings.transmit.share.hint.off": "关闭 — Nexus 运行时其他程序无法使用电台。开启后将它们指向此处出现的地址（<em>Hamlib NET rigctl</em>）。",
  "settings.transmit.share.hint.direct": "驱动某个<em>非</em>活动电台：使用其直连地址 <code>{{address}}</code>（每台电台独立；每当 Nexus 重新配置该电台时，此链路会短暂断开）。",
  "settings.transmit.foreignPtt.label": "其他程序可触发发射",
  "settings.transmit.foreignPtt.hint": "开启：共享程序（WSJT-X、VarAC）可触发电台，正如它独占 CAT 线缆时那样 — Nexus 的所有发射安全措施仍然适用。关闭：共享程序可调谐与读取，但绝不会发射。",
  "settings.transmit.tciServer.label": "通过 TCI 共享",
  "settings.transmit.tciServer.hint.off": "关闭。开启后，本机上支持 TCI 的程序（如 <b>WSJT-X</b>、<b>JTDX</b>、<b>MSHV</b> 和 <b>Log4OM</b>）可通过此处出现的地址经 Nexus 使用电台。",
  "settings.transmit.tciServer.hint.on": "本机程序连接到此地址，如同连接到某 SDR 程序的 TCI 服务器。在 WSJT-X 与 JTDX 中，选择电台 <em>TCI Client RX1</em> 并将此地址作为其 TCI 服务器。它们跟随当前活动电台：可对其调谐、切换边带并降低功率（绝不升高），并获取其接收音频。仅本机程序可连接，绝不来自另一台电脑，也绝不来自网页。保存时生效。",
  "settings.transmit.tciServer.waiting": "尚未监听。程序可连接后地址将出现于此。若你刚开启，请先保存。",
  "settings.transmit.tciServer.port.label": "TCI 服务器端口",
  "settings.transmit.tciServer.port.hint": "WSJT-X、JTDX 和 MSHV 寻找 40001。第二个 Nexus 窗口使用下一端口，上方地址始终显示正在使用的那个。仅当本机另一程序已占用时才更改。",
  "settings.transmit.tciServer.tx.label": "TCI 上的程序可发射",
  "settings.transmit.tciServer.tx.hint": "关闭：程序可调谐与读取，但绝不发射。开启：当 Nexus 处于语音屏幕时，程序可用其自身音频或电台麦克风触发电台，在 CW 屏幕发送 CW 宏，并调谐。其自身音频仅在它请求了语音模式（USB、LSB、AM 或 FM）后才发出。WSJT-X 与 JTDX 仅在模式与 Nexus 不同时才请求模式，因此当 Nexus 已在 USB 时设为 USB，它们请求无内容并被拒绝。Nexus 的所有发射安全措施仍然适用：Nexus 中 TX 必须开启，停止 TX 优先且保持，且任何内容都不会越过你的执照或功率限制。程序绝不会开启 TX。仅可在电台处设置。",
  "settings.transmit.tciServer.tx.slotTimed": "FT8、FT4 及其他时隙定时模式尚可能无法通过 TCI 发射。在 Nexus 测量其给这些时序增加的延迟之前，会拒绝程序的数字化发射。",
  "settings.transmit.tciServer.cw.label": "来自程序的 CW 宏",
  "settings.transmit.tciServer.cw.hint": "日志记录器的 TCI 键控器（Log4OM、5MContest）通过 Nexus 发送其 CW 宏，仅在 CW 屏幕，且仅在程序可发射期间。任何程序都能停止 CW。",
  "settings.transmit.tciServer.spots.label": "来自程序的呼号点报",
