  "aprs.health.wrongFreqMode.detail": "电台在 {{dial}} {{mode}} — APRS 需要 {{want}} FM。此频道上任何内容都无法按 APRS 分组解码，无论音频电平显示什么。请调到 APRS 频道。",
  "aprs.health.wrongFreq.detail": "电台在 {{dial}} — APRS 需要 {{want}}。此频道上任何内容都无法按 APRS 分组解码，无论音频电平显示什么。请调到 APRS 频道。",
  "aprs.health.noCapture.label": "无输入",
  "aprs.health.noCapture.detail": "已启用，但完全没有音频样本到达 — 采集设备没有送出任何数据。请检查 设置 ▸ 电台 ▸ 音频 中的输入设备（接收）是否为电台（而不是麦克风或已断开的设备）；扬声器里听到的声音并不代表应用正在采集的声音。",
  "aprs.health.decoding.label": "已解码 {{count}} 个",
  "aprs.health.decoding.detail": "启用以来已解码 {{count}} 个分组。实时 {{level}}。",
  "aprs.health.decoding.detail.aged": "启用以来已解码 {{count}} 个分组，最近一次在 {{age}}。实时 {{level}}。",
  "aprs.health.unreadable.label": "{{count}} 个 CRC 校验失败",
  "aprs.health.unreadable.detail": "启用以来听到 {{count}} 个突发，最近一次在 {{age}} — 均未通过校验。其中一部分属正常：若静噪在突发中途打开，分组开头会丢失，残缺的分组永远无法通过。只有当从未解出任何内容时才算故障 — 那时请检查电台是否在 {{channel}} 且为 FM。{{advice}} 最近一次突发峰值为 {{burst}}；实时 {{level}}。",
  "aprs.health.advice.clipping": "该突发正在削波（峰值 {{peak}}，有 {{samples}} 个样本顶到上限）— 请降低电台的 USB AF 输出电平，或降低该设备在 Windows 中的输入电平。分组能承受相当程度的削波，因此这损失的是余量而非解码率，但也没必要顶到上限。",
  "aprs.health.advice.quiet": "该突发峰值为 {{peak}}，远低于健康区间 {{min}} 至 {{max}} — 请提高电台的 USB AF 输出电平（IC-9700：SET > Connectors > USB AF Output Level）或该设备在 Windows 中的输入电平。这能留出抗噪余量；但它本身并不是校验失败的原因。",
  "aprs.health.silent.label": "静音",
  "aprs.health.silent.detail": "输入正常并正在送音频，但内容是静音 — 通常只表示分组之间静噪关闭，这正是空闲 FM 频道的样子。要确认路由是否正确，请打开静噪：嘶声应当在此显示为电平。若打开静噪后仍显示静音，说明选错了输入设备。实时 {{level}}。",
  "aprs.health.listening.label": "监听中",
  "aprs.health.listening.detail": "音频已到达解码器，但近期未听到分组 — 频道安静。实时 {{level}}。打开静噪时，嘶声应约为 {{hiss}}；分组突发的峰值应在 {{min}} 至 {{max}}。",
