  "js8.dock.hbNet.title.on": "心跳组网已开启：HB 会发送你的心跳，HB ACK 可能会应答你听到的心跳。点击关闭（会被记住）；正在运行的心跳重复会停止。",
  "js8.dock.hbNet.title.speed": "在 {{speed}} 速率下不发送心跳：JS8Call 仅在 Slow、Normal 和 Fast 下发送心跳及其确认。在你更改速率之前 HB 会隐藏，而此开关会保留其设置。",
