  "js8.dock.estimate.title": "这需要占用多少周期的空口时间（每周期一帧）。仅为估算 — 引擎会实际打包，并拒绝任何超过十分钟空口时长的内容。",
  "js8.dock.autoreply.title.off": "自动回复已关闭 — 发给你的 SNR?、GRID?、INFO? 或 STATUS? 的答复，以及对 MSG 或中继的 ACK，会放入消息框由你自行发送，与 JS8Call 一致，绝不自行发射；QUERY MSGS 不会得到应答。点击开启（会被记住）。仅在发射开启时才会应答。",
  "js8.dock.autoreply.title.on": "自动回复已开启，但发射已关闭 — 不会发射；回复会显示为“本应回复”。启用发射（顶栏胶囊）后回复才会发出。",
  "js8.dock.autoreply.title.armed": "自动回复已就绪：发给你的、或发给你加入的组的 SNR?、GRID?、INFO?、QUERY 和 MSG 都会得到应答，若设置在询问时要求确认，则在你说“是”之后回复。点击关闭。",
  "js8.dock.relay.title.off": "中继已关闭 — 经你转发的 > 消息只显示，不再传递。点击开启（会被记住）。中继属于第三方信息，你需对其负责。",
