  "js8.dock.relay.title.armed": "中继已就绪：经你转发的 > 消息会以 *DE* 你的呼号 重新发送，最后一跳会被确认。若自动回复关闭，则改为放入消息框由你发送。点击关闭。",
  "js8.dock.relay.notArmed.needsAuto": "中继已开启，但自动回复关闭时，转发的消息会放入消息框由你发送，绝不自行发射。开启自动回复才能在空口上中继。",
  "js8.dock.hbAck.title.off": "心跳确认已关闭（JS8Call 的默认设置）。点击可用 HEARTBEAT SNR 应答心跳（会被记住）。仅在发射开启时才会应答。",
