  "js8.dock.hbAck.title.armed": "心跳确认已就绪：每听到一次心跳，就在随机空闲时隙用 HEARTBEAT SNR 应答。点击关闭。",
  "js8.dock.hbAck.notArmed.needsHb": "心跳确认已开启，但与 JS8Call 一致，只有在心跳组网（HB NET）开启时才会应答。HB NET 本身不发送任何内容。",
  "js8.dock.hbAck.notArmed.needsAuto": "心跳确认已开启，但与 JS8Call 一致，只有在自动回复开启时才会应答。请开启自动回复。",
