  "phone.pane.log.title": "日志",
  "phone.txContract.aria": "发射实况 — 你按键时真正发出的内容",
  "phone.txContract.freq.title": "你下一次发段实际发射的频率 — 由引擎自身给出，已计入确认的异频和 XIT 偏移。异频状态下，这并非你的接收频率。",
  "phone.txContract.freq.commanded.title": "Nexus 根据其下发的指令推算出该频率，无法全部与电台核对 — 或者没有 CAT 链路，或者启用了 XIT 且 clarifier 只写不读，因此在电台上拧出的偏移不会显示在这里。",
  "phone.txContract.noEmission.title": "该台站未报告发射频率。Nexus 不会用你的接收频率顶替 — 异频状态下二者是无关的数字。",
  "phone.txContract.repeaterShift.title": "在 FM 中继场景下，Nexus 无法给出你的发射频率 — 频移由电台施加，不在引擎报告的频率中，因此在此打印只会是贴着发射标签的接收频率。请在 设置 ▸ 电台 中核对频移，或直接在电台上查看。",
  "phone.txContract.mode.title": "你下一次发段所用的模式，以及 Nexus 的来源。这与日志写入的是同一次回读，因此此处所见与记录内容不会矛盾。",
  "phone.txContract.split.title": "你的发射频率相对接收频率的偏移（kHz）",
  "phone.txContract.split.commanded.title": "Nexus 向电台请求了该异频。快照不包含电台自身的确认，因此这里显示的是下发值而非回读值 — 若堆积中对方听不到你，请在电台上核对。",
  "phone.txContract.xit.title": "发射微调 — 叠加到发射频率上的偏移（Hz）",
  "phone.txContract.xit.commanded.title": "Nexus 无法从任何电台读回 XIT，因此这里显示的是 Nexus 下发的值 — 未必是发射机的实际位置。在电台自身 clarifier 旋钮上设置的偏移不会出现在这里。",
  "phone.txContract.power.title": "你的功率设置，以及电台最近一次实际测得的输出。无标记时：若 CAT 有回报则为电台回读值，否则为最后一次下发值，且无法区分是哪种。",
