  "phone.analog.af.aria": "音频增益",
  "phone.analog.af.title": "音频增益 — 电台自身音量。若你的声卡取自电台扬声器或耳机口，它也会决定解码器听到的电平，因此把它调到很低会同时停掉 FT8、RTTY、PSK 和扬声器输出。自带 USB 音频、或使用固定电平 ACC/DATA 接口的电台不受影响。",
  "phone.analog.af.mutesDecode.label": "解码？",
  "phone.analog.af.mutesDecode.title": "音频增益几乎调到最低。若解码器通过电台扬声器或耳机口收听，它也已静音。请提高音频增益，或改用 USB 编解码器或后部 ACC/DATA 接口供声卡，这些不受此控件影响。",
  "phone.analog.rf.aria": "射频增益",
  "phone.analog.rf.title": "射频增益 — 控制接收前端，不是发射功率。在强信号波段上把它调低，可把信号从 AGC 正在压着的噪声中提出来。",
  "phone.analog.sql.aria": "静噪",
  "phone.analog.sql.title": "静噪 — 信号需达到的电平门槛。FM 下正常使用；在 SSB、CW 和数据模式下请完全打开，因为多数电台（包括 USB 音频通路）静噪关闭时会同时静音解码器所听的音频。",
  "phone.analog.sql.mutesDecode.label": "解码？",
  "phone.analog.sql.mutesDecode.title": "在 FM 之外的模式下静噪仍开着。多数电台此时会连同解码器所听的音频一起静音，因此在有信号打破静噪之前什么都解不出来。SSB、CW 和数据模式下请把它完全关到底。",
