  "settings.contestPick.entryClass.label": "参赛等级",
  "settings.contestPick.entryClass.hint": "主办方按本竞赛自身规则为你评比的等级，写入 Cabrillo 日志的 ENTRY-CLASS 行。在伊利诺伊 QSO 聚会中，同时使用多部发射机的俱乐部参加 UNLIMITED，高功率与低功率等级以 100 瓦 PEP 为界。要证明 QRP 参赛，请在功率类别中选择 QRP。",
  "settings.contestPick.club.label": "俱乐部",
