  "settings.contestPick.operators.label": "其他操作员",
  "settings.contestPick.operators.hint": "Cabrillo 日志的 OPERATORS 行会列出记录联络时被设为“操作员”的所有人。此处可补充其他人，呼号之间用空格或逗号分隔。",
  "settings.contestPick.transmitter.label": "多人类别",
  "settings.contestPick.transmitter.aria": "你参加的多人类别",
  "settings.contestPick.transmitter.hint": "你的多人参赛同时在空中的信号数，按本竞赛主办方评比的类别：ONE 为同时一个（多人单机、多人单发射机），TWO 为多人双机，UNLIMITED 为多人多机，LIMITED 为 ARRL VHF 竞赛的受限多人。它写入 Cabrillo 日志的 CATEGORY-TRANSMITTER 行，同时附上主办方要求多人参赛提供的 OPERATORS 行。Nexus 会把所有联络标记为发射机 0，因此在提交多人双机日志前，请自行补入第二台发射机的联络。",
  "settings.contestPick.overlay.label": "附加类别",
  "settings.contestPick.overlay.aria": "你还参加的附加类别",
  "settings.contestPick.overlay.hint": "在你参赛组别之外、主办方另行评比的附加类别，写入 CATEGORY-OVERLAY 行 — 前提是你符合其规则（CQ 的附加类别面向单人操作）。对 Rookie 与 Youth，CQ 要求在 soapbox 中写明首次获照日期或出生年份。",
  "settings.contestPick.address.label": "邮寄地址",
  "settings.contestPick.address.hint": "主办方寄送证书或奖牌所用的地址，写入 Cabrillo 日志的 ADDRESS 行：街道在此，每行一条，其余填入下方各框。主办方模板中没有对应行的部分会再写一行 ADDRESS，按其模板的写法。留空则省略地址。远程功能永远不会看到它。",
  "settings.contestPick.address.city": "邮寄城市",
