  "settings.contestPick.band.aria": "你参加的波段类别",
  "settings.contestPick.band.hint": "全波段参赛选 ALL，单波段参赛选其所用的那一个波段，写入 Cabrillo 日志的 CATEGORY-BAND 行。单波段参赛仍会记录所有联络（含其他波段），主办方只评比此处指定的波段。在 CQ 系列中，多人参赛为 ALL。留空则省略该行。",
  "settings.contestPick.soapbox.label": "Soapbox",
