  "settings.rigControl.txAudio.hint": "Nexus 通过 CAT 键控时，使用电台的哪一路音频输入发射。<b>前面板/麦克风</b>是 Nexus 一直以来的键控方式。<b>后部/数据</b>改为键控数据输入：如果你的声卡是通过后部 DATA 或 ACC 接口（SignaLink 插的地方）或电台自带的 USB 音频接入电台，且电台在 VOX 下有声、换 Nexus 就没有声音，就选它。话音操作台的 PTT 不受影响，仍按原有方式键控电台。<b>按电台分别设置。</b>",
  "settings.rigControl.pttPort.label": "PTT 串口",
