  "settings.rigControl.catRts.label": "接口通过 CAT 端口的 RTS 键控",
  "settings.rigControl.catRts.hint": "如果你的接口是通过 CAT 端口的 RTS 线键控电台（Digirig Mobile 及大多数单线接口都是这样接的），请勾选此项。Nexus 随后会保持 RTS 为低电平，而不是让它悬空 — 悬空时某些电台会在端口一打开就进入发射。<b>如果你的电台在 Nexus 一启动就发射，就是这个设置。</b>若是一根普通串口线直连电台，请保持关闭：电台可能正用这根线做流控，夺走它可能让 CAT 失效。",
