  "settings.rigControl.icomLan.hint": "<b>Beta：仅接收与控制。</b>Nexus 不在此连接上发射，也尚不传输音频。电台侧：开启 Network Control（重启后生效）和 CI-V Transceive。电台一次只接受一个网络程序，请先关闭 wfview 或 RS-BA1。仅限 LAN 与 Wi-Fi：从其他网络访问请用 VPN。",
