  "settings.rigControl.icomLan.port.label": "控制端口（UDP）",
  "settings.rigControl.icomLan.port.hint": "默认为 50001，除非你在电台上改过。",
  "settings.rigControl.icomNative.icomlan": "在 Icom 网络连接下始终开启：Nexus 正是靠它在电台上操控电台。",
  "settings.rigControl.conn.tci": "TCI（SDR 程序）— Beta",
  "settings.rigControl.tci.hint": "<b>Beta。</b>Nexus 连接 SDR 程序自带的 TCI 服务器，无需 rigctld，也无需虚拟 COM 口。它读取并设置频率与模式，并通过该程序发射。开启<b>经 TCI 传输音频</b>后，接收音频与 Nexus 自身的发射音频也走 TCI。<b>尚未就绪：</b>通过程序自带键控器发 CW（请改用声卡键控器）。请先在程序中开启 TCI 服务器。",
  "settings.rigControl.tci.host.label": "SDR 程序地址",
  "settings.rigControl.tci.host.hint": "运行 SDR 程序的电脑：<b>127.0.0.1</b> 表示本机。TCI 无密码也无加密，因此只能在自己的网络中访问其他电脑。",
  "settings.rigControl.tci.port.label": "TCI 端口",
  "settings.rigControl.tci.port.hint": "程序 TCI 设置中的端口：ExpertSDR3 与 Thetis 出厂为 50001，piHPSDR 为 40001。<b>查找 TCI 服务器</b>会把两个都试一遍。",
  "settings.rigControl.tci.find.label": "TCI 服务器",
  "settings.rigControl.tci.find.action": "查找 TCI 服务器",
