  "settings.rigControl.tci.find.title": "在此地址查找 SDR 程序的 TCI 服务器：先试当前端口，再试 50001 和 40001。它只读取服务器自报的信息；从不发射，也从不改变电台。",
  "settings.rigControl.tci.find.searching": "正在 {{host}} 查找 TCI 服务器…",
  "settings.rigControl.tci.find.found": "在 {{address}} 找到 TCI 服务器：{{server}}。",
  "settings.rigControl.tci.find.unnamed": "它未提供自己的名称",
