  "settings.cw.macros.role.askRepeat": "请求重发",
  "settings.cw.macros.role.query": "询问",
  "settings.rtty.legend": "RTTY",
  "settings.rtty.rxAutoArm.label": "打开 RTTY 时开始接收",
  "settings.rtty.rxAutoArm.hint": "RTTY 界面一打开就启动解码器 — 调到某个信号上文字就会打印，无需设置。关闭此项则需手动启用接收（解码文本窗格中的“启用接收”按钮）。这只会启用接收机 — 发射绝不会替你启用。",
  "settings.rtty.keying.title": "键控",
  "settings.rtty.backend.label": "键控后端",
  "settings.rtty.backend.afsk": "AFSK — 声卡音调经电台以 LSB 发送（默认）",
  "settings.rtty.backend.fsk": "真 FSK — 串口键控线（DTR/RTS），电台处于 RTTY 模式",
  "settings.rtty.backend.hint": "Nexus 如何发送 RTTY。<b>AFSK</b> 通过与 FT8 相同的发射音频通路播放双音波形（由声卡定时 = 无抖动；请调整驱动力使 ALC 刚好读到零）。<b>真 FSK</b> 通过一条串口控制线按位翻转电台的 FSK 输入、电台处于 RTTY 模式 — 从而解锁其窄带 RTTY 滤波器（例如 FTDX10 的）— PTT 走 CAT 或它自己的线。软件 FSK 的时序只到休闲/Field Day 水平；AFSK 是时序最干净的路径。",
  "settings.rtty.afskSideband.label": "AFSK 边带",
  "settings.rtty.afskSideband.lsb": "LSB（标准）",
  "settings.rtty.afskSideband.hint": "电台跑 AFSK 所用的边带。LSB 是 RTTY 惯例。在 USB 下，Nexus 会把电台置入其上部数据模式（DATA-U / USB-D / DIGU）并自行交换音调，这样 mark 在空中仍是高音，解码器照样能抄收 — 请保持“反向”关闭。",
  "settings.rtty.fskPort.label": "FSK 串口",
  "settings.rtty.fskPort.placeholder": "例如 FTDX10 的 USB Enhanced COM",
  "settings.rtty.fskPort.hint": "其控制线馈送电台 FSK 输入的端口。留空 = 使用 CAT 串口。",
  "settings.rtty.fskLine.label": "FSK 数据线",
  "settings.rtty.fskLine.dtr": "DTR（常见接法 — RTS 留给 PTT）",
  "settings.rtty.fskLine.hint": "哪条控制线承载数据位。PTT 必须走它自己独立的通路 — CAT PTT 或独立的 PTT 线，绝不能用这条；若两者冲突，Nexus 会拒绝发送。",
  "settings.rtty.signal.title": "信号",
  "settings.rtty.baud.label": "波特率",
  "settings.rtty.baud.hf": "45.45 — HF 标准",
  "settings.rtty.baud.vhf": "75 — VHF / 部分网络",
  "settings.rtty.baud.hint": "同时驱动发射位时钟与接收解调器（真 45.45，绝不取整为 45）。",
  "settings.rtty.shift.label": "频移（Hz）",
  "settings.rtty.shift.hf": "170 — HF 标准",
  "settings.rtty.shift.hint": "mark/space 间距 — 同时用于发射音调对与接收解调器。",
  "settings.rtty.reverse.label": "反向（交换 mark/space）",
  "settings.rtty.reverse.hint": "在发射和接收解码器中交换 mark 与 space，用于与颠倒发射的台站通联。不要用它来跑 USB：请改选 AFSK 边带，它会自行保持正确的极性。",
  "settings.rtty.autoCall.title": "自动呼叫",
  "settings.rtty.autoListen.label": "重发前先听",
  "settings.rtty.autoListen.hint": "自动呼叫在再次呼叫 CQ 之前等待多久（秒）— 以及向某台请求重发前的相同等待。计时从你本次发射完全结束开始，而不是从排队时开始。<b>30 秒</b>是自动呼叫一直以来的做法；只有在你想让节奏更快或更慢时才改。低于 5 秒会在你刚刚请求的答复上直接键控，因此下限是 5。",
  "settings.rtty.autoRepeats.label": "放弃前的重试次数",
  "settings.rtty.autoRepeats.hint": "自动呼叫在一次联络中向某台再请求多少次后才放手。<b>这不会限制 CQ。</b>无人应答的 CQ 会一直重复直到你停止 — 这正是“停止”按钮和 TX 开关的用途。",
  "settings.psk.legend": "PSK",
  "settings.psk.rxAutoArm.label": "打开 PSK 时开始接收",
  "settings.psk.rxAutoArm.hint": "PSK 界面一打开就启动解码器 — 在瀑布图上点击一条迹线，文字就会打印，无需设置。关闭此项则需手动启用接收（解码文本窗格中的“启用接收”按钮）。你自己停止接收机的状态会在本次会话内记住。这只会启用接收机 — 发射绝不会替你启用。",
  "settings.jtty.title": "JTTY",
  "settings.jtty.rxAutoArm.label": "打开 JTTY 时开始接收",
  "settings.jtty.rxAutoArm.hint": "JTTY 界面一打开就启动其解码器。关闭此项则需手动启用接收（“全部解码”窗格中的“启用接收”按钮）。你自己停止接收机的状态会在本次会话内记住。这只会启用接收机 — 发射绝不会替你启用。",
  "settings.js8.legend": "JS8",
  "settings.js8.receiving.title": "速度与接收",
  "settings.js8.speed.label": "发射速度",
  "settings.js8.speed.hint": "你的帧以何种速度发送，以及 TX 时钟跟随的周期：Slow 30 秒、Normal 15 秒、Fast 10 秒、JS8 40 6 秒、JS8 60 4 秒。波段上大多用 Normal。JS8 40（JS8Call 3.0 之前称为 Turbo）和 JS8 60 用于强信号；JS8Call 3.0 将 JS8 60 标为实验性。JS8 顶栏的速度胶囊改动的是同一个设置。",
  "settings.js8.rxSpeeds.label": "解码这些速度",
  "settings.js8.rxSpeeds.hint": "默认同时解码所有速度，与 JS8Call 一致 — 同一波段上的 Slow 台站和 JS8 60 台站都会打印出来。取消勾选某个速度可在小机器上节省 CPU；每条活动行都标有其速度字母（E/A/B/C/I）。在 JS8 60 出现之前保存的列表会保留原有四个速度：勾选 JS8 60 即可加入。",
  "settings.js8.callsignAgingMin.label": "呼号老化（分钟）",
  "settings.js8.callsignAgingMin.hint": "默认关闭（0），与 JS8Call 一致。否则，若某台站已有这么多分钟未被听到，就会从台站列表中移除，除非你选中了它或它有给你的未读消息，且你的 HEARING? 回复也会排除它。最大 1440（一天）。",
  "settings.js8.activityAgingMin.label": "波段活动老化（分钟）",
  "settings.js8.activityAgingMin.hint": "默认 2，与 JS8Call 一致。若“波段活动”窗格中某行的最新解码已过这么多分钟，该行会离开窗格，除非 RX 正落在它的偏移上。0 表示保留所有行。最大 1440（一天）。",
  "settings.js8.freq.title": "频率",
  "settings.js8.returnToLastDial.label": "回到上次使用的频率",
  "settings.js8.returnToLastDial.hint": "默认关闭，与 JS8Call 一致。开启后，打开 JS8 会把电台调回你上次在 JS8 中使用的频率，而不是该波段的 JS8 频率。",
  "settings.js8.freqs.label": "JS8 频率",
  "settings.js8.freqs.hint.stock": "JS8Call 建议的频率。改动、增加或删除任一项后，列表就变成你自己的：JS8 中的波段选择器会显示它，打开 JS8 时调谐到该波段上的第一个。",
  "settings.js8.freqs.hint.own": "你自己的列表：JS8 中的波段选择器会显示它，打开 JS8 时调谐到该波段上的第一个。重置可恢复 JS8Call 的建议频率。",
