  "settings.js8.schedule.label": "按计划更换频率",
  "settings.js8.schedule.hint": "默认关闭，与 JS8Call 一致。开启后，Nexus 会在下列时间自行更换电台频率，无人值守：先提示，30 秒后执行更改，除非你取消。绝不在发射时或消息正在发送时进行。",
  "settings.js8.schedule.list.label": "计划表（UTC）",
