  "settings.confirmations.eqsl.upload.label": "自动上传 QSO 到 eQSL",
  "settings.confirmations.eqsl.upload.hint": "记录 QSO 时即上传到 eQSL.cc（需要上方的 eQSL 用户名 + 密码）。",
  "settings.confirmations.qrz.username.label": "QRZ 用户名",
